/**
 * The plain `Dockerfile` written next to service.json. `tdk up` does not build it: for generated
 * resources the engine builds `.autogenerated/Dockerfile.app.autogenerated`. It is a starting point
 * for building the service image outside TDK, so its port follows the service's `port`.
 */
export function getDockerfileTemplate(port, healthCheckPath) {
    // `oven/bun` has no curl, so the probe uses bun itself.
    const healthcheck = healthCheckPath
        ? `# Health check
HEALTHCHECK --interval=10s --timeout=5s --retries=3 \\
  CMD bun -e "fetch('http://localhost:${port}${healthCheckPath}').then((r) => process.exit(r.ok ? 0 : 1), () => process.exit(1))"

`
        : "";
    return `# Scaffolded by \`tdk resource\`. \`tdk up\` does NOT build this file: it builds
# .autogenerated/Dockerfile.app.autogenerated (golden layers, project root as context).
# Use this one as a starting point for building the image outside TDK, and keep its
# port in step with "port" in service.json.
FROM oven/bun:1.2

WORKDIR /app

# Copy package files (bun.lock is optional: a TDK workspace keeps it at the project root)
COPY package.json bun.lock* ./

# Install dependencies
RUN bun install

# Copy source
COPY . .

# Build if needed
RUN bun run build

${healthcheck}ENV PORT=${port}
EXPOSE ${port}

CMD ["bun", "run", "start"]
`;
}
export function getShutdownHandlerTemplate(signal) {
    return `process.on('${signal}', () => {
  console.log('[Worker] ${signal} received, shutting down gracefully...');
  process.exit(0);
});`;
}
export function getWorkerIndexTemplate(name) {
    return `console.log('🚀 ${name} worker started');

interface Job {
  id: string;
  type: string;
  payload: Record<string, unknown>;
  priority?: number;
  timestamp?: string;
}

const CONFIG = {
  pollIntervalMs: parseInt(process.env.WORKER_POLL_INTERVAL || '5000'),
  maxRetries: parseInt(process.env.WORKER_MAX_RETRIES || '3'),
  batchSize: parseInt(process.env.WORKER_BATCH_SIZE || '10'),
};

async function processJob(job: Job): Promise<void> {
  console.log('[Worker] Processing job:', job.id, 'type:', job.type);

  // Add job processing logic here using job.payload

  await new Promise(resolve => setTimeout(resolve, 1000));
  console.log('[Worker] Job completed:', job.id);
}

let demoJobSent = false;

async function fetchJobs(): Promise<Job[]> {
  // Connect to your queue (Redis, RabbitMQ, etc.) and fetch jobs.
  // Until you do, hand out one demo job on the first poll so the loop runs end to end; remove this with the queue.
  if (demoJobSent) return [];
  demoJobSent = true;
  return [{ id: 'demo-1', type: 'demo', payload: {} }];
}

async function main() {
  console.log('[Worker] Configuration:', CONFIG);

  while (true) {
    try {
      const jobs = await fetchJobs();

      if (jobs.length === 0) {
        await new Promise(resolve => setTimeout(resolve, CONFIG.pollIntervalMs));
        continue;
      }

      console.log(\`[Worker] Fetched \${jobs.length} jobs\`);

      for (const job of jobs) {
        try {
          await processJob(job);
        } catch (error: unknown) {
          console.error('[Worker] Job failed:', error);
        }
      }
    } catch (error: unknown) {
      console.error('[Worker] Error in main loop:', error);
      // Wait before retrying to avoid tight error loops
      await new Promise(resolve => setTimeout(resolve, CONFIG.pollIntervalMs));
    }
  }
}

${getShutdownHandlerTemplate("SIGTERM")}

${getShutdownHandlerTemplate("SIGINT")}

main().catch((err) => {
  console.error('[Worker] Fatal error:', err);
  process.exit(1);
});
`;
}
export function getTestTemplate(name) {
    return `import { describe, it, expect } from 'vitest';

describe('${name}', () => {
  it('should pass a basic test', () => {
    expect(true).toBe(true);
  });
});
`;
}
